const{chromium}=require('playwright');const out={http5xx:[],pageErrors:[],filters:[],viewports:[]};(async()=>{const b=await chromium.launch({headless:true,executablePath:'/ms-playwright/chromium-1187/chrome-linux/chrome',args:['--no-sandbox']});const p=await b.newPage({viewport:{width:1440,height:900},locale:'ar-SA'});p.on('pageerror',e=>out.pageErrors.push(e.message));p.on('console',m=>{if(m.type()==='error'&&!/status of 401|status of 404/.test(m.text()))out.pageErrors.push(m.text())});p.on('response',r=>{if(r.status()>=500)out.http5xx.push(`${r.status()} ${r.url()}`)});await p.route('https://tile.openstreetmap.org/**',r=>r.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/pN8AAAAASUVORK5CYII=','base64')}));const base='http://host.docker.internal:8080';const summaryWait=p.waitForResponse(r=>new URL(r.url()).pathname==='/api/data-dashboard/geography-summary',{timeout:60000});const mapWait=p.waitForResponse(r=>new URL(r.url()).pathname==='/api/data-dashboard/geography',{timeout:60000});await p.goto(`${base}/?view=data-dashboard`,{waitUntil:'domcontentloaded'});const [sr,mr]=await Promise.all([summaryWait,mapWait]);const summary=await sr.json(),map=await mr.json();out.initial={summaryStatus:sr.status(),mapStatus:mr.status(),masters:summary.unique_master_total,mapped:summary.mapped_unique_masters,mapMasters:map.counts.total,mapMapped:map.counts.exact_mapped,mapPoints:map.points.length,outside:map.counts.outside_boundary};if(sr.status()!==200||mr.status()!==200||summary.unique_master_total!==6657||summary.mapped_unique_masters!==5889||map.counts.outside_boundary!==0)throw Error(`Initial dashboard/map contract failed ${JSON.stringify(out.initial)}`);await p.waitForFunction(()=>document.querySelector('#rdGeoStats')?.textContent.includes('نقاط موثقة'),null,{timeout:15000});await p.locator('#rdOpportunityMap').scrollIntoViewIfNeeded();await p.waitForFunction(()=>document.querySelectorAll('#rdOpportunityMap .leaflet-marker-icon').length>0,null,{timeout:25000});
const reg=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('region_id')==='5'},{timeout:60000});await p.locator('#dashRegionFilter').selectOption('5');let rr=await reg;if(rr.status()!==200)throw Error('Region map reload failed');out.filters.push('region');await p.waitForFunction(()=>!document.querySelector('#dashGovernorateFilter').disabled,null,{timeout:10000});const gov=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('governorate_id')==='501'},{timeout:60000});await p.locator('#dashGovernorateFilter').selectOption('501');let gr=await gov;if(gr.status()!==200)throw Error('Governorate map reload failed');out.filters.push('governorate');await p.locator('#rdFilterPanel').evaluate(e=>e.open=true);const src=p.waitForResponse(r=>{const u=new URL(r.url());return u.pathname==='/api/data-dashboard/geography'&&u.searchParams.get('source')==='ncp'},{timeout:60000});await p.locator('#dashSource').selectOption('ncp');let sr2=await src;if(sr2.status()!==200)throw Error('NCP map reload failed');out.filters.push('NCP source');await p.locator('#dashReset').click();await p.waitForResponse(r=>new URL(r.url()).pathname==='/api/data-dashboard/geography'&&!new URL(r.url()).search,{timeout:60000});await p.locator('#rdOpportunityMap').scrollIntoViewIfNeeded();await p.waitForFunction(()=>document.querySelectorAll('#rdOpportunityMap .leaflet-marker-icon').length>0,null,{timeout:30000});
let popup=p.locator('#rdOpportunityMap [data-map-open]').first();for(let i=0;i<16&&await popup.count()===0;i++){let dots=p.locator('#rdOpportunityMap .rd-marker-icon');if(await dots.count()){await dots.first().click({force:true});await p.waitForTimeout(300);popup=p.locator('#rdOpportunityMap [data-map-open]').first();if(await popup.count())break;}let clusters=p.locator('#rdOpportunityMap .rd-cluster-icon');if(await clusters.count()){await clusters.last().click({force:true});await p.waitForTimeout(300);}popup=p.locator('#rdOpportunityMap [data-map-open]').first();}if(!await popup.count())throw Error('Live map did not open a marker popup');const ids=await popup.getAttribute('data-map-open');const list=p.waitForResponse(r=>r.url().includes('/api/opportunities?')&&new URL(r.url()).searchParams.get('map_ids')===ids,{timeout:20000});await popup.click({force:true});const lr=await list;if(lr.status()!==200||!p.url().includes(`map_ids=${ids}`))throw Error('Map-to-list drilldown failed');await p.waitForFunction(()=>document.querySelectorAll('#opportunityRows [data-detail]').length>0,null,{timeout:15000});await p.locator('#opportunityRows [data-detail]').first().click({force:true});await p.waitForFunction(()=>document.querySelector('#modal.show'),null,{timeout:10000});await p.locator('#modalClose').click({force:true});out.drilldown='marker popup → filtered Opportunities → detail';
await p.goto(`${base}/?view=data-dashboard`,{waitUntil:'domcontentloaded'});await p.waitForTimeout(400);for(const[w,h]of[[1920,1080],[1440,900],[1366,768],[768,900],[390,844]]){await p.setViewportSize({width:w,height:h});await p.waitForTimeout(200);let f=await p.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,mapWidth:document.querySelector('#rdOpportunityMap')?.getBoundingClientRect().width||0,filterVisible:!!document.querySelector('#dashRegionFilter')?.getClientRects().length}));if(f.mapWidth<100||!f.filterVisible||f.scroll>f.width+1)throw Error(`Responsive ${w}x${h}: ${JSON.stringify(f)}`);out.viewports.push({viewport:`${w}x${h}`,...f});}await b.close();if(out.http5xx.length||out.pageErrors.length)throw Error(JSON.stringify(out));console.log(JSON.stringify(out));})().catch(e=>{console.error(e);process.exit(1)});